package fr.cercle.tourderole;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import org.json.*;import java.util.*;import java.math.*;import java.time.*;
public final class Domain{
static void b(MainActivity a,LinearLayout body,String title,MainActivity.Work w){a.addButton(body,title,()->a.attempt(w));}
static void filter(MainActivity a,String tab,String key,String id){a.current=tab;a.filterKey=key;a.filterValue=id;a.query="";a.home();}
static String s(JSONObject r,String k){return r.optString(k);}static void set(JSONObject r,String k,Object v)throws Exception{r.put(k,v);r.put("modified",System.currentTimeMillis());}
static BigDecimal sum(MainActivity a,String tab,String key,String id,String amount){BigDecimal v=BigDecimal.ZERO;JSONArray all=a.rows(tab);for(int i=0;i<all.length();i++){JSONObject r=all.optJSONObject(i);if(key.isEmpty()||r.optString(key).equals(id))try{v=v.add(Core.amount(r.optString(amount)));}catch(Exception ignored){}}return v;}
public static void actions(MainActivity a){String f=a.feature();if(f.equals("cartes")){b(a,a.root,"Réviser les fiches dues",()->review(a,""));}if(f.equals("valise")&&a.current.equals("listes"))b(a,a.root,"Créer une liste week-end",()->weekend(a));if(f.equals("journal"))b(a,a.root,"Chercher une date",()->{Calendar c=Calendar.getInstance();new DatePickerDialog(a,(v,y,m,d)->{a.query=String.format(Locale.ROOT,"%04d-%02d-%02d",y,m+1,d);a.home();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();});if(f.equals("defis")){b(a,a.root,"Tirer une mission photo",()->mission(a));HashMap<String,Integer> scores=new HashMap<>();JSONArray done=a.rows("resultats");for(int i=0;i<done.length();i++){String name=done.optJSONObject(i).optString("participant","Sans nom");if(name.isEmpty())name="Sans nom";scores.put(name,scores.getOrDefault(name,0)+1);}if(!scores.isEmpty()){StringBuilder label=new StringBuilder("Défis validés : ");for(Map.Entry<String,Integer> score:scores.entrySet())label.append(score.getKey()).append(" ").append(score.getValue()).append(" · ");a.root.addView(a.text(label.toString(),14,a.accent));}}if(f.equals("documents"))b(a,a.root,"Fusionner des PDF",()->a.pick("application/pdf",30,true));if(f.equals("cuisine")&&a.current.equals("menus"))b(a,a.root,"Courses manquantes · sept prochains jours",()->shopping(a));if(f.equals("tirages")&&a.current.equals("listes"))a.root.addView(a.text("Ouvre une liste pour lancer son tirage.",14,a.muted));if(f.equals("timers"))a.root.addView(a.text("Les séquences continuent en arrière-plan. Alertes approximatives selon Android.",13,a.muted));if(f.equals("enquetes"))Investigations.actions(a);}
public static void detail(MainActivity a,LinearLayout body,String tab,JSONObject r){String f=a.feature(),id=s(r,"id");
if(f.equals("prets")||f.equals("livres")&&tab.equals("prets"))b(a,body,"Marquer comme rendu",()->{set(r,"statut","Rendu");set(r,"retour",Core.today());AlarmReceiver.cancel(a,id);r.remove("_alarm");a.save();a.detail(tab,r);});
if((f.equals("placard")||f.equals("cuisine"))&&tab.equals("stock")){a.horizontalButtons(body,a.button("+1",()->a.attempt(()->quantity(a,tab,r,1))),a.button("−1",()->a.attempt(()->quantity(a,tab,r,-1))));b(a,body,"Ajouter aux courses",()->{JSONObject c=a.insert("courses",s(r,"nom"));c.put("quantite","1");c.put("unite",s(r,"unite"));a.save();a.toast("Ajouté aux courses.");});}
if(hasField(a,tab,"fait")&&!(f.equals("defis")&&tab.equals("defis")))b(a,body,r.optString("fait").equals("1")?"Marquer à faire":"Marquer terminé",()->{set(r,"fait",s(r,"fait").equals("1")?"0":"1");a.save();a.detail(tab,r);});
if(f.equals("taches")&&tab.equals("taches")){b(a,body,"Fait · passer au suivant",()->{String person=s(r,"responsable");if(person.isEmpty())person=Core.nextPerson(s(r,"personnes"),"");if(person.isEmpty())throw new Exception("Ajoute au moins un participant.");JSONObject h=a.insert("historique",s(r,"nom"));h.put("personne",person);h.put("date",Core.today());set(r,"responsable",Core.nextPerson(s(r,"personnes"),person));set(r,"echeance",Core.nextDate(Core.today(),Math.max(1,Core.intValue(s(r,"frequence"),7))));a.save();a.detail(tab,r);});}
if(f.equals("valise")&&tab.equals("listes")){b(a,body,"Ouvrir les objets de ce voyage",()->filter(a,"objets","liste",id));b(a,body,"Tout décocher pour ce voyage",()->{JSONArray all=a.rows("objets");for(int i=0;i<all.length();i++)if(all.optJSONObject(i).optString("liste").equals(id))all.optJSONObject(i).put("fait","0");a.save();a.toast("Liste décochée.");});b(a,body,"Dupliquer ce voyage et ses objets",()->{JSONObject copy=new JSONObject(r.toString());copy.put("id",UUID.randomUUID().toString());copy.put("nom",s(r,"nom")+" · copie");copy.put("modified",System.currentTimeMillis());a.rows("listes").put(copy);JSONArray all=a.rows("objets");int n=all.length();for(int i=0;i<n;i++)if(all.optJSONObject(i).optString("liste").equals(id)){JSONObject item=new JSONObject(all.optJSONObject(i).toString());item.put("id",UUID.randomUUID().toString());item.put("liste",copy.optString("id"));item.put("fait","0");all.put(item);}a.save();a.detail(tab,copy);});}
if(f.equals("projets")&&tab.equals("projets")){BigDecimal actual=sum(a,"achats","projet",id,"cout"),budget=Core.amount(s(r,"budget"));body.addView(a.text("Dépenses : "+Core.money(actual)+"\nBudget restant : "+Core.money(budget.subtract(actual)),20,a.accent));b(a,body,"Achats de ce projet",()->filter(a,"achats","projet",id));b(a,body,"Carnet de ce projet",()->filter(a,"notes","projet",id));}
if(f.equals("plantes")&&tab.equals("plantes")){b(a,body,"Arrosage effectué aujourd’hui",()->{JSONObject h=a.insert("soins","Arrosage · "+s(r,"nom"));h.put("plante",id);h.put("date",Core.today());set(r,"echeance",Core.nextDate(Core.today(),Math.max(1,Core.intValue(s(r,"frequence"),7))));a.save();a.detail(tab,r);});b(a,body,"Historique des soins",()->filter(a,"soins","plante",id));}
if(f.equals("voiture")&&tab.equals("vehicules")){body.addView(a.text("Dépenses enregistrées : "+Core.money(sum(a,"interventions","vehicule",id,"cout").add(sum(a,"depenses","vehicule",id,"cout"))),19,a.accent));b(a,body,"Entretien de ce véhicule",()->filter(a,"interventions","vehicule",id));b(a,body,"Dépenses de ce véhicule",()->filter(a,"depenses","vehicule",id));}
if(f.equals("livres")&&tab.equals("livres")){int current=Core.intValue(s(r,"page"),0),max=Core.intValue(s(r,"pages"),0);body.addView(a.text(max>0?"Progression : "+Math.min(100,current*100/max)+" %":"Renseigne le nombre de pages pour afficher la progression.",18,a.accent));b(a,body,"+10 pages lues",()->{int next=Core.intValue(s(r,"page"),0)+10,total=Core.intValue(s(r,"pages"),0);if(total>0)next=Math.min(total,next);set(r,"page",""+next);set(r,"statut",total>0&&next==total?"Terminé":"En cours");a.save();a.detail(tab,r);});b(a,body,"Citations de ce livre",()->filter(a,"citations","livre",id));}
if(f.equals("cartes")&&tab.equals("paquets"))b(a,body,"Réviser ce paquet",()->review(a,id));
if(f.equals("cartes")&&tab.equals("cartes")){long due=r.optLong("_due",0);body.addView(a.text(due==0?"Fiche nouvelle":due<=System.currentTimeMillis()?"Fiche à réviser":"Prochaine révision : "+new java.text.SimpleDateFormat("dd/MM/yyyy HH:mm",Locale.FRANCE).format(new Date(due)),16,a.accent));}
if(f.equals("timers")){long finish=a.getSharedPreferences("timers",0).getLong(id,0);if(finish>0){TextView timer=a.text(Core.timer(finish-System.currentTimeMillis()),32,a.accent);body.addView(timer);a.timerViews.put(id,timer);}b(a,body,"Démarrer / redémarrer",()->{long[] durations=Core.durations(s(r,"durees"));if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);long when=System.currentTimeMillis()+durations[0];a.getSharedPreferences("timers",0).edit().putLong(id,when).putInt(id+"_step",0).apply();AlarmReceiver.schedule(a,tab,r,when,true);a.detail(tab,r);});b(a,body,"Arrêter ce minuteur",()->{AlarmReceiver.cancel(a,id);a.detail(tab,r);});}
if(f.equals("audio")&&tab.equals("audios")){b(a,body,"Lire / reprendre",()->a.play(r,0));b(a,body,"Ajouter un signet à la position actuelle",()->{if(AudioService.mp==null||!AudioService.currentId.equals(id))throw new Exception("Lance cet audio avant de poser un signet.");JSONObject mark=a.insert("signets","Signet · "+Core.timer(AudioService.mp.getCurrentPosition()));mark.put("audio",id);mark.put("position",""+(AudioService.mp.getCurrentPosition()/1000));a.save();a.toast("Signet enregistré.");});b(a,body,"Signets de cet audio",()->filter(a,"signets","audio",id));}
if(f.equals("audio")&&tab.equals("signets"))b(a,body,"Reprendre ici",()->{JSONObject audio=a.find("audios",s(r,"audio"));if(audio==null)throw new Exception("Audio introuvable");a.play(audio,Core.intValue(s(r,"position"),0)*1000L);});
if(f.equals("documents")&&r.optString("_label").toLowerCase(Locale.ROOT).endsWith(".pdf"))b(a,body,"Extraire des pages en PDF image",()->Documents.split(a,r));
if(f.equals("defis")&&tab.equals("defis"))b(a,body,"Valider avec la photo jointe",()->{if(!s(r,"_mime").startsWith("image/"))throw new Exception("Ajoute une photo à ce défi avant de valider.");if(s(r,"fait").equals("1")){a.toast("Défi déjà validé.");return;}JSONObject done=a.insert("resultats",s(r,"nom"));done.put("participant",s(r,"participant"));done.put("date",Core.today());done.put("notes",s(r,"objectif"));done.put("_file",s(r,"_file"));done.put("_label",s(r,"_label"));done.put("_mime",s(r,"_mime"));set(r,"fait","1");a.save();a.detail(tab,r);});
if(f.equals("tirages")&&tab.equals("listes")){b(a,body,"Tirer une option",()->draw(a,r));b(a,body,"Options de cette liste",()->filter(a,"options","liste",id));b(a,body,"Historique des résultats",()->filter(a,"historique","liste",id));}
if(f.equals("maison")&&tab.equals("pieces")){body.addView(a.text("Travaux enregistrés : "+Core.money(sum(a,"travaux","piece",id,"cout")),18,a.accent));for(String t:new String[]{"equipements","travaux","stocks","documents"})b(a,body,a.schema(t).optString("title")+" de cette pièce",()->filter(a,t,"piece",id));}
if(f.equals("maison")&&tab.equals("equipements"))b(a,body,"Documents de cet équipement",()->filter(a,"documents","equipement",id));
if(f.equals("cuisine")&&tab.equals("recettes"))b(a,body,"Prévoir cette recette au menu",()->{JSONObject m=a.insert("menus",s(r,"nom"));m.put("recette",id);m.put("date",Core.today());a.save();a.edit("menus",m);});
if(f.equals("reader")&&r.has("_file"))b(a,body,"Lire avec reprise",()->Reader.open(a,r));
if(f.equals("enquetes"))Investigations.detail(a,body,tab,r);
}
static boolean hasField(MainActivity a,String tab,String key){JSONArray fs=a.schema(tab).optJSONArray("fields");for(int i=0;i<fs.length();i++)if(fs.optJSONObject(i).optString("k").equals(key))return true;return false;}
static void quantity(MainActivity a,String tab,JSONObject r,int delta)throws Exception{BigDecimal value=Core.amount(s(r,"quantite")).add(BigDecimal.valueOf(delta)).max(BigDecimal.ZERO);set(r,"quantite",value.stripTrailingZeros().toPlainString());a.save();a.detail(tab,r);}
static void weekend(MainActivity a)throws Exception{JSONObject trip=a.insert("listes","Week-end");trip.put("jours","2");for(String item:new String[]{"Documents","Téléphone et chargeur","Sous-vêtements","Vêtements de rechange","Trousse de toilette","Médicaments personnels","Chaussures adaptées"}){JSONObject r=a.insert("objets",item);r.put("liste",trip.optString("id"));r.put("quantite","1");r.put("fait","0");}a.save();a.detail("listes",trip);}
static void review(MainActivity a,String deck){JSONArray all=a.rows("cartes");JSONObject pick=null;long now=System.currentTimeMillis();for(int i=0;i<all.length();i++){JSONObject r=all.optJSONObject(i);if(!deck.isEmpty()&&!r.optString("paquet").equals(deck))continue;if(r.optLong("_due")<=now&&(pick==null||r.optLong("_due")<pick.optLong("_due")))pick=r;}if(pick==null){a.info("Révisions","Aucune fiche à échéance. Ajoute des fiches ou reviens à la date prévue.");return;}JSONObject card=pick;new AlertDialog.Builder(a).setTitle("Question").setMessage(card.optString("nom")).setNegativeButton("Arrêter",null).setPositiveButton("Voir la réponse",(d,w)->{new AlertDialog.Builder(a).setTitle("Réponse").setMessage(card.optString("reponse")).setNeutralButton("À revoir",(x,n)->grade(a,card,deck,0)).setNegativeButton("Demain",(x,n)->grade(a,card,deck,1)).setPositiveButton("Facile",(x,n)->grade(a,card,deck,2)).show();}).show();}
static void grade(MainActivity a,JSONObject r,String deck,int g){a.attempt(()->{long due=Core.review(System.currentTimeMillis(),g,r.optInt("_days",1));r.put("_due",due);r.put("_days",g==0?0:g==1?1:Math.min(365,Math.max(2,r.optInt("_days",1)*2)));a.save();review(a,deck);});}
static void draw(MainActivity a,JSONObject list)throws Exception{String id=list.optString("id");int avoid=Math.max(0,Core.intValue(list.optString("eviter"),0));HashSet<String> recent=new HashSet<>();JSONArray history=a.rows("historique");for(int i=history.length()-1;i>=0&&recent.size()<avoid;i--){JSONObject h=history.optJSONObject(i);if(h.optString("liste").equals(id))recent.add(Core.norm(h.optString("nom")));}ArrayList<JSONObject> eligible=new ArrayList<>();ArrayList<Integer> weights=new ArrayList<>();JSONArray all=a.rows("options");for(int i=0;i<all.length();i++){JSONObject r=all.optJSONObject(i);if(r.optString("liste").equals(id)&&!r.optString("exclu").equals("1")&&!recent.contains(Core.norm(r.optString("nom")))){eligible.add(r);weights.add(Core.intValue(r.optString("poids"),1));}}int ix=Core.weighted(weights,new Random());if(ix<0)throw new Exception("Aucune option éligible. Ajoute des options ou réduis l’exclusion des derniers résultats.");JSONObject picked=eligible.get(ix),h=a.insert("historique",picked.optString("nom"));h.put("liste",id);h.put("date",Core.today());a.save();a.info("Résultat",picked.optString("nom"));}
static void shopping(MainActivity a)throws Exception{ArrayList<String> stock=new ArrayList<>();JSONArray pantry=a.rows("stock");for(int i=0;i<pantry.length();i++){JSONObject r=pantry.optJSONObject(i);if(Core.amount(r.optString("quantite")).signum()>0)stock.add(r.optString("nom"));}LinkedHashSet<String> missing=new LinkedHashSet<>();JSONArray menus=a.rows("menus");LocalDate now=LocalDate.now();for(int i=0;i<menus.length();i++){JSONObject m=menus.optJSONObject(i);if(m.optString("fait").equals("1")||!Core.date(m.optString("date"))||m.optString("date").isEmpty())continue;LocalDate date=LocalDate.parse(m.optString("date"));if(date.isBefore(now)||date.isAfter(now.plusDays(6)))continue;JSONObject recipe=a.find("recettes",m.optString("recette"));if(recipe!=null)for(String line:recipe.optString("ingredients").split("\\n"))if(!line.trim().isEmpty()&&!Core.hasIngredient(line,stock))missing.add(line.trim());}int created=0;for(String line:missing){boolean exists=false;JSONArray all=a.rows("courses");for(int i=0;i<all.length();i++)if(!all.optJSONObject(i).optString("fait").equals("1")&&Core.ingredient(all.optJSONObject(i).optString("nom")).equals(Core.ingredient(line)))exists=true;if(!exists){JSONObject r=a.insert("courses",line);r.put("quantite","À vérifier");created++;}}a.save();a.info("Liste de courses",created+" ingrédient(s) ajouté(s). Comparaison par nom ; vérifie les quantités nécessaires.");}
static void mission(MainActivity a)throws Exception{String[] actions={"Trouve un reflet","Photographie une ombre intéressante","Cherche un objet bleu","Repère trois formes rondes","Capture un détail que tu ignores d’habitude","Trouve une texture rugueuse","Photographie une symétrie","Cherche une lettre dans un paysage","Trouve deux couleurs qui se répondent","Montre quelque chose de minuscule","Observe un objet sous un angle inhabituel","Photographie une trace du temps","Trouve un motif répété","Capture quelque chose de transparent","Cherche une ligne qui guide le regard","Photographie un contraste clair et sombre","Trouve une forme dans les nuages","Montre un objet qui raconte un souvenir","Photographie une porte singulière","Cherche une plante dans un lieu inattendu","Trouve une perspective amusante","Photographie une lumière douce","Capture une matière brillante","Cherche une combinaison de trois couleurs"};HashSet<String> used=new HashSet<>();JSONArray all=a.rows("defis");for(int i=0;i<all.length();i++)used.add(all.optJSONObject(i).optString("nom"));ArrayList<String> options=new ArrayList<>();for(String s:actions)if(!used.contains(s))options.add(s);if(options.isEmpty())throw new Exception("Toutes les missions ont été tirées. Tu peux créer tes propres défis.");String mission=options.get(new Random().nextInt(options.size()));JSONObject r=a.insert("defis",mission);r.put("objectif",mission+". Pense au cadrage et à ce que tu veux montrer.");a.save();a.detail("defis",r);}
}
